pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amt) public {
        // Keep amt in a reasonable wide domain but non-zero to be meaningful
        vm.assume(depositor != address(0));
        amt = bound(amt, 1 wei, 10 ether);

        // Fund depositor and perform Put as depositor
        vm.deal(depositor, amt);
        vm.prank(depositor);

        bool ok;
        // call Put and capture if it succeeded (non-reverting)
        try c.Put{value: amt}(block.timestamp + 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: if Put call returned (did not revert),
        // then Acc[depositor].balance must equal the deposited amt (since initially 0)
        // We express this as a single assertTrue reading c's public getter.
        // If the mutated contract leaves the lock set, subsequent interactions by the same
        // caller may revert and thus ok==false for some inputs; here we only assert
        // when the call succeeded that the balance reflects the deposit.

        // Read balance via public getter Acc(address).balance mapping auto-getter
        uint bal = c.Acc(depositor).balance;

        // Exactly one assertTrue as required: if call succeeded then balance == amt
        assertTrue(!ok || bal == amt);
    }
}

