pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor (msg.sender) and unlockTime candidate and deposit amount
    function testFuzz_property(address actor, uint256 unlockTime, uint256 deposit) public {
        // keep actor usable
        vm.assume(actor != address(0));
        // bound deposit to a reasonable range so vm.deal works and MinSum logic doesn't interfere too narrowly
        deposit = bound(deposit, 0, 10 ether);
        // set block timestamp to a stable, known value
        vm.warp(1_000_000);

        // fund the actor and call Put as that actor with provided unlockTime and deposit
        vm.deal(actor, deposit);
        vm.prank(actor);
        // perform payable call; if deposit is zero it's still valid
        c.Put{value: deposit}(unlockTime);

        // single assertion: after Put, the stored unlockTime for actor must be >= block.timestamp
        // This is true for reference contract (it sets max(_unlockTime, block.timestamp)).
        // The mutant that assigns directly can set a past unlockTime and make this false for some inputs.
        (uint storedUnlockTime,,) = getHolder(actor);
        assertTrue(storedUnlockTime >= block.timestamp);
    }

    // helper to read the public mapping's Holder fields via the auto-generated getter
    function getHolder(address a) internal view returns (uint unlockTime, uint balance, address dummy) {
        // The mapping is public: Acc(address) returns (uint unlockTime, uint balance)
        // But solidity auto-getter signature may vary; to be safe we call the public getter directly.
        // However we cannot declare the exact tuple if the contract C's getter returns only two values.
        // So call via interface of C's public getter: Acc(address) returns (uint,uint)
        (unlockTime, balance) = c.Acc(a);
        dummy = a; // satisfy triple return
    }
}

