pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    AttackerLog atkLog;

    function setUp() public { 
        // deploy C with address(this) as log per instructions, then we will replace log by calling Put via attacker that uses its own log behavior
        c = new C(address(this));
        // deploy a reentrant log (attacker) which will call back into C during AddMessage
        atkLog = new AttackerLog(address(c));
    }

    // fuzz parameters: sender address, deposit amount, unlockTime candidate
    function testFuzz_property(address sender, uint256 amount, uint256 unlockTime) public {
        // admissible domain: amount should be > 0 and not exceed a large bound to avoid trivial overflow issues
        vm.assume(amount > 0 && amount < type(uint128).max);
        // make sender a funded EOA
        vm.deal(sender, amount);

        // The attacker Log contract needs to be the LogFile used by C. Because C was constructed with address(this),
        // we cannot change its LogFile field externally; instead we'll perform the Put call by having the sender be the attacker
        // and the attacker will forward to c.Put while using its own behaviour in AddMessage. To do that, we instruct the attacker
        // contract to perform the deposit on behalf of sender (pranked) and let it call c.Put with its own address as msg.sender
        // So we will have the attacker contract receive funds from sender then call c.Put. We simulate sender sending ETH to attacker.

        // First, sender sends ETH to attacker
        vm.prank(sender);
        (bool sent,) = address(atkLog).call{value: amount}("");
        require(sent);

        // Now instruct attacker to call c.Put with the given unlockTime. The attacker will in its AddMessage reenter into c."
        // Use vm.prank to make the subsequent call appear from the attacker contract itself when it calls c.Put.
        // The attacker contract executes the flow: call c.Put(unlockTime) using its held balance and its own Log behavior.
        atkLog.doPut(address(c), unlockTime);

        // After the Put call finishes, the general invariant we assert is that c.Acc(address(atkLog)).balance >= amount
        // (specifically balance increased by at least the amount deposited). We read the public mapping Acc via autogenerated getter.
        (uint unlockT, uint bal) = c.Acc(address(atkLog));

        // Single assertion: the reference guarantees the recorded balance for the caller (attacker) is >= amount
        assertTrue(bal >= amount);
    }
}

// Minimal attacker log contract which both acts as a Log (with AddMessage) and can receive funds and call C.Put.
contract AttackerLog {
    address public target;

    constructor(address _target) payable {
        target = _target;
    }

    // receive ETH from fuzz harness
    receive() external payable {}

    // This function performs the Put call on target using the contract's own balance.
    function doPut(address caddr, uint _unlockTime) public {
        // call Put on C from this contract, forwarding all ETH it holds
        C(caddr).Put{value: address(this).balance}(_unlockTime);
    }

    // Log-like function that C will call: AddMessage(address,uint,string).
    // To attempt to break mutants that reorder/assume state, this AddMessage will reenter target once.
    function AddMessage(address _adr, uint _val, string memory _data) public {
        // reenter target harmlessly: call a view or a no-op function if exists; we'll attempt a balance query via address
        // We do a low-level call to target to simulate reentrancy attempt; if target had a payable fallback it might be invoked.
        // Keep it simple: call a non-existent function to trigger fallback on some variants; ignore return.
        (bool,) = address(target).call(abi.encodeWithSignature("nonexistent()"));
        // do nothing else
    }
}

