        c = new C(address(this)); 
        // deploy attacker log which will re-enter into c during AddMessage
        attackerLog = new MaliciousLog(address(c));
    }

    // Fuzz: actor and amount and unlockTime
    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        // keep actor non-zero and amount within reasonable bounds
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 5 ether); // allow zero as well

        // fund actor so it can send value
        vm.deal(actor, amount);

        // replace the LogFile in c by using constructor arg was address(this), but contract exposes no setter.
        // However C constructor used given address; to route through attacker we deploy a fresh C with attacker log.
        // redeploy c with attackerLog address
        c = new C(address(attackerLog));

        // read starting balance for actor in contract
        uint256 before = c.Acc(actor).balance;

        // perform Put from actor sending amount and fuzzed unlockTime
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // read after
        uint256 after = c.Acc(actor).balance;

        // The invariant: after == before + amount for the correct reference contract for all inputs.
        // The mutant that assigns unlockTime directly can be exploited by MaliciousLog reentering to break this invariant for some inputs.
        assertTrue(after == before + amount);
    }
}

// Malicious log that re-enters into C during AddMessage to attempt to break ordering in the mutant
contract MaliciousLog {
    C target;
    bool reentered;
    constructor(address _t) { target = C(_t); }

    // this function has same selector as AddMessage(address,uint,string) when called from C
    // it will attempt to call back into target.Put with zero value to trigger possible reentrancy during Put
    // Note: signature must match (address,uint,string) but solidity allows arbitrary function here; low-level call from C will invoke fallback if signature mismatches.
    fallback() external payable {
        // only reenter once to avoid infinite loop
        if (!reentered) {
            reentered = true;
            // attempt a low-value reentry (no ether) to disturb state in mutant
            // call Put with unlockTime = 0
            try target.Put{value: 0}(0) {
            } catch {
            }
        }
    }
}

