        // Keep values in wide admissible ranges
        vm.assume(sendAmt > 0);
        // limit sendAmt to something reasonable so vm.deal works in fuzzing
        sendAmt = bound(sendAmt, 1, 1 ether * 1000);
        // actor must be non-zero
        vm.assume(actor != address(0));

        // ensure actor has funds
        vm.deal(actor, sendAmt);

        // choose a warped block timestamp so we can test providedUnlock relative to block time
        // bound providedUnlock to cover both <= and > block.timestamp cases
        providedUnlock = bound(providedUnlock, 0, type(uint64).max);
        // set a known block time
        uint256 baseTime = uint256(1_650_000_000); // arbitrary fixed base
        vm.warp(baseTime);

        // now pick providedUnlock centered around baseTime to allow both cases
