import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: caller address and a candidate unlock time.
    // The rule: after calling Put with some _unlockTime, Acc[caller].unlockTime must be >= min(_unlockTime, block.timestamp)
    // (i.e., the contract never sets unlockTime below the earlier of provided time and now). The mutant that forces
    // unlockTime = block.timestamp can violate this when _unlockTime > block.timestamp because then min(_unlockTime, block.timestamp) == block.timestamp
    // but the preserved future time property is expected to be >= that min. This phrasing avoids equals-only formulations tried before.
    function testFuzz_property(address caller, uint256 _unlockTime) public {
        // keep caller non-zero to be an admissible actor
        vm.assume(caller != address(0));

        // fund caller so it can send value
        uint256 send = 1 ether;
        vm.deal(caller, send);

        // advance time slightly to make block.timestamp nonzero but otherwise unrestricted
        vm.warp(block.timestamp + 1);

        // perform the Put call as the fuzzed caller with fuzzed _unlockTime
        vm.prank(caller);
        c.Put{value: send}(_unlockTime);

        // read back stored unlockTime via the public mapping getter
        (uint256 storedUnlockTime, ) = c.Acc(caller);

        // The general invariant we assert: storedUnlockTime >= min(_unlockTime, block.timestamp)
